/* Filter Button Container */
.filter-button-container { position: absolute; left: 40px; top: 20px; width: calc(100% - 40px); overflow-x: hidden; padding: 20px 0; }

.filter-button-tooltip { position: absolute; width: auto; left: 15px; top: 24px; z-index: 100; border-radius: 4px; width: auto; -webkit-animation: tooltip-bounce 2s infinite; animation: tooltip-bounce 2s infinite; margin-left: 15px; white-space: nowrap; opacity: 0; overflow: visible; -webkit-transition: opacity 0.3s; transition: opacity 0.3s; pointer-events: none; padding: 0 20px; background-color: #333; color: #fff; -webkit-box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15); box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15); font-size: 15.7px; line-height: 48px; top: 20px; }

.filter-button-tooltip.tooltip-visible { opacity: 1; }

.filter-button-tooltip:before { content: ""; position: absolute; width: 0; height: 0; top: calc(50% - 3px); content: ""; left: -3px; -webkit-box-sizing: border-box; box-sizing: border-box; border: 5px solid black; border-color: transparent transparent #333 #333; -webkit-transform-origin: 0 0; transform-origin: 0 0; -webkit-transform: rotate(45deg) translateY(-50%); transform: rotate(45deg) translateY(-50%); -webkit-box-shadow: -2px 2px 2px 0 rgba(0, 0, 0, 0.15); box-shadow: -2px 2px 2px 0 rgba(0, 0, 0, 0.15); }

@-webkit-keyframes tooltip-bounce { 0%, 20%, 50%, 80%, 100% { -webkit-transform: translateX(0); transform: translateX(0); }
  40% { -webkit-transform: translateX(14px); transform: translateX(14px); }
  60% { -webkit-transform: translateX(7px); transform: translateX(7px); } }

@keyframes tooltip-bounce { 0%, 20%, 50%, 80%, 100% { -webkit-transform: translateX(0); transform: translateX(0); }
