.message-bubble .message-text:before { content: ""; width: 0; height: 0; border-top: 6px solid transparent; border-bottom: 6px solid transparent; border-right: 6px solid #f4f4f4; left: -6px; right: auto; top: 19px; position: absolute; }

.message-bubble.me .message-text:before { border-top: 6px solid transparent; border-bottom: 6px solid transparent; border-left: 6px solid #2a41e8; border-right: none; right: -6px; left: auto; }

/* Message Time Sign */
.message-time-sign { text-align: center; display: block; position: relative; margin-bottom: 25px; }

.message-time-sign:before { content: ""; height: 1px; background-color: #eaeaea; display: block; max-width: 30%; margin: 0 auto; position: relative; top: 14px; z-index: 10; }

.message-time-sign span { background-color: #fff; font-size: 14px; color: #888; z-index: 11; position: relative; padding: 0 10px; }

/* Reply */
.message-reply { border-top: 1px solid #eaeaea; padding: 30px; display: -webkit-box; display: -ms-flexbox; display: flex; -webkit-box-align: start; -ms-flex-align: start; align-items: flex-start; margin-top: 15px; }

.message-reply textarea { min-width: auto; height: 48px; min-height: 48px; padding: 10px 0; margin: 0 15px 0 0; -webkit-box-flex: 1; -ms-flex: 1; flex: 1; font-size: 15px; font-weight: 400; line-height: 26px; -webkit-box-shadow: none; box-shadow: none; border: none; -webkit-box-sizing: border-box; box-sizing: border-box; resize: none; }

.message-reply button { border-radius: 4px; -webkit-box-flex: 1; -ms-flex: auto; flex: auto; -webkit-box-flex: 0; -ms-flex-positive: 0; flex-grow: 0; height: 44px; text-align: center; -ms-flex-item-align: center; align-self: center; padding: 0 25px; }

.message-reply i { padding: 0; margin: 0; }

/* Typing Indicastor */
.typing-indicator { width: auto; height: 24px; padding-top: 8px; }

.typing-indicator span { height: 8px; width: 8px; float: left; margin: 0 1px; background-color: #a0a0a0; display: block; border-radius: 50%; opacity: 0.4; }

.typing-indicator span:nth-of-type(1) { -webkit-animation: 1s blink infinite 0.33333s; animation: 1s blink infinite 0.33333s; }

.typing-indicator span:nth-of-type(2) { -webkit-animation: 1s blink infinite 0.66666s; animation: 1s blink infinite 0.66666s; }

.typing-indicator span:nth-of-type(3) { -webkit-animation: 1s blink infinite 0.99999s; animation: 1s blink infinite 0.99999s; }

@-webkit-keyframes blink { 50% { opacity: 1; } }

@keyframes blink { 50% { opacity: 1; } }

