/* ---------------------------------- */
/* Common Styles
------------------------------------- */
body { color: #666; font-size: 16px; line-height: 27px; background-color: #fff; font-family: "Nunito", sans-serif; text-transform: none; }

body.gray { background-color: #fbfbfb; }

body p { font-size: 16px; line-height: 27px; }

/* Main Font */
h1, h2, h3, h4, h5, h6 { font-family: "Nunito", sans-serif; text-transform: none; }

input[type="text"], input[type="password"], input[type="email"] { font-family: "Nunito", sans-serif; text-transform: none; }

textarea, select { font-family: "Nunito", sans-serif; text-transform: none; }

input[type="button"], input[type="submit"] { font-family: "Nunito", sans-serif; text-transform: none; }

button, body .pac-container { font-family: "Nunito", sans-serif; text-transform: none; }

/* Headlines */
h1, h2, h3, h4, h5, h6 { color: #333; font-weight: 500; margin: 0; padding: 0; }

h1 { font-size: 32px; }

h2 { font-size: 26px; }

h3 { font-size: 22px; }

h4 { font-size: 16px; }

h5 { font-size: 14px; }

h6 { font-size: 12px; }

h3.page-title { font-size: 20px; line-height: 32px; }

.section { display: block; }

.section.white { background: #fff; }

.section.gray { background: #f9f9f9; }

.section.border-top { border-top: 1px solid #e0e0e0; }

.section.border-bottom { border-bottom: 1px solid #e0e0e0; }

/* Section Headline */
.section-headline { display: block; position: relative; padding-right: 20%; }

.section-headline.centered { text-align: center; padding: 0; }

.section-headline span { font-size: 18px; line-height: 26px; font-weight: 300; color: #888; margin-top: 0; display: block; }

.section-headline h1, .section-headline h2, .section-headline h3 { font-size: 26px; line-height: 36px; font-weight: 500; color: #333; }

.section-headline h4 { font-size: 26px; line-height: 36px; font-weight: 500; color: #333; font-size: 22px; line-height: 34px; }

.section-headline.border-top { border-top: 1px solid #e0e0e0; }

h1.in-a-box, h2.in-a-box, h3.in-a-box, h5.in-a-box { display: inline-block; font-size: 18px; background-color: #333; color: #fff; border-radius: 4px; padding: 8px 20px; -webkit-box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15); box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15); }

.section-headline h5 { font-size: 16px; font-weight: 600; line-height: 30px; }

/*
/* Single Task / Job / Profile Headings */
.single-page-section { margin-bottom: 55px; display: block; }

.single-page-section p { white-space: pre-wrap; }

.single-page-section p:last-of-type { padding-bottom: 0; margin-bottom: 0; }

.single-page-section h3 { margin-bottom: 20px; font-size: 20px; }

.single-page-section .job-listing h3.job-listing-title { margin-bottom: 0; }

/* Headline Link */
a.headline-link { position: absolute; right: 0; bottom: 0; }

a.headline-link.bottom-icon:after { content: "\e957"; top: 3px; }

a.headline-link:after { content: "\e995"; font-family: "Material-Icons"; font-size: 21px; line-height: 0; position: relative; top: 4px; margin-left: 5px; }

@media (max-width: 768px) { a.headline-link { position: relative; margin-top: 10px; display: inline-block; } }

/* Classes for disabling things on mobile devices */
@media (max-width: 992px) { .hide-under-992px { display: none; } }

@media (max-width: 768px) { .hide-under-768px { display: none; } }

@media (max-width: 480px) { .hide-under-480px { display: none; } }

/* Content & Sidebar Offsets */
.content-left-offset { padding-left: 30px; }

.content-right-offset { padding-right: 30px; }

@media (max-width: 992px) { .content-left-offset { padding-left: 15px; }
  .content-right-offset { padding-right: 15px; } }

